/* Reset and base styles */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
    line-height: 1.6;
    color: #333;
    background: #fff;
}

.container {
    max-width: 800px;
    margin: 0 auto;
    padding: 0 20px;
}

/* Header */
header {
    background: #2c3e50;
    color: #fff;
    padding: 60px 0 40px;
    margin-bottom: 60px;
}

header h1 {
    font-size: 2.5em;
    margin-bottom: 10px;
    font-weight: 700;
}

.tagline {
    font-size: 1.2em;
    opacity: 0.9;
    font-weight: 300;
}

/* Main content */
main {
    margin-bottom: 80px;
}

section {
    margin-bottom: 60px;
}

h2 {
    font-size: 2em;
    margin-bottom: 30px;
    color: #2c3e50;
    font-weight: 600;
}

h3 {
    font-size: 1.4em;
    margin-bottom: 15px;
    color: #34495e;
    font-weight: 600;
}

p {
    margin-bottom: 20px;
}

.lead {
    font-size: 1.2em;
    line-height: 1.8;
    color: #555;
}

/* Approach boxes */
.approach {
    margin-bottom: 30px;
    padding-left: 20px;
    border-left: 4px solid #3498db;
}

.approach h3 {
    color: #3498db;
    margin-bottom: 10px;
}

/* Project cards */
.project {
    margin-bottom: 40px;
    padding: 25px;
    background: #f8f9fa;
    border-radius: 8px;
    border-left: 4px solid #2c3e50;
}

.project h3 {
    margin-bottom: 8px;
}

.project h3 a {
    color: #2c3e50;
    text-decoration: none;
}

.project h3 a:hover {
    color: #3498db;
    text-decoration: underline;
}

.project-meta {
    font-size: 0.9em;
    color: #7f8c8d;
    margin-bottom: 15px;
}

/* Lists */
ul {
    margin-left: 30px;
    margin-bottom: 20px;
}

li {
    margin-bottom: 10px;
}

/* Links */
a {
    color: #3498db;
    text-decoration: none;
}

a:hover {
    text-decoration: underline;
}

/* Footer */
footer {
    background: #ecf0f1;
    padding: 40px 0;
    text-align: center;
    color: #7f8c8d;
    font-size: 0.9em;
}

footer p {
    margin-bottom: 10px;
}

/* Responsive */
@media (max-width: 600px) {
    header h1 {
        font-size: 2em;
    }

    .tagline {
        font-size: 1em;
    }

    h2 {
        font-size: 1.6em;
    }

    .lead {
        font-size: 1.1em;
    }
}

